// This code has been fully generated by an AI.

// Package importer turns FIT files into stored activities.
//
// Pipeline per file: decode → archive the raw file by content hash →
// derive stream and simplified track → upsert by natural key. Every step is
// deterministic, so importing the same file again changes nothing and a new
// AnalysisVersion re-derives all activities from the archived raw files.
package importer

import (
	"bytes"
	"compress/gzip"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"math"
	"os"
	"path/filepath"
	"time"

	"github.com/stefanluchs/my-velo/internal/analysis"
	"github.com/stefanluchs/my-velo/internal/fitfile"
	"github.com/stefanluchs/my-velo/internal/geo"
	"github.com/stefanluchs/my-velo/internal/sport"
	"github.com/stefanluchs/my-velo/internal/store"
)

// AnalysisVersion identifies the derivation logic. Increase it when stream,
// track or metric derivation changes; Reanalyze then re-derives all
// activities from their archived raw files.
//
//  1. stream, track, summary metrics
//  2. training values, laps/splits, best efforts
//  3. time in zones, thresholds, own load (NP, TSS, TRIMP)
const AnalysisVersion = 3

// StreamEncoding describes how activity streams are stored.
const StreamEncoding = "json+gzip;v1"

// Statuses beyond those of store.SaveRecording.
const (
	// StatusFailed marks a file that could not be imported.
	StatusFailed store.SaveStatus = "failed"
	// StatusSkipped marks a valid FIT file that is no activity (monitoring,
	// sleep, settings …); the Garmin export contains thousands of them.
	StatusSkipped store.SaveStatus = "skipped"
)

// Importer imports FIT files into a store.
type Importer struct {
	Store  *store.Store
	RawDir string // archive of original files, named by SHA-256
	Logger *slog.Logger
}

// Result describes the outcome for one file.
type Result struct {
	Origin     string           `json:"origin"`
	Key        string           `json:"key,omitempty"`
	ActivityID int64            `json:"activity_id,omitempty"`
	Status     store.SaveStatus `json:"status"`
	Error      string           `json:"error,omitempty"`
	Sport      string           `json:"sport,omitempty"`
	SubSport   string           `json:"sub_sport,omitempty"`
	StartTime  time.Time        `json:"start_time,omitzero"`
	TZOffsetS  int              `json:"tz_offset_s,omitempty"`
	DistanceM  float64          `json:"distance_m,omitempty"`
}

// Stats counts results by status.
type Stats struct {
	Created, Updated, Unchanged, Skipped, Failed int
}

// Add counts r.
func (s *Stats) Add(r Result) {
	switch r.Status {
	case store.Created:
		s.Created++
	case store.Updated:
		s.Updated++
	case store.Unchanged:
		s.Unchanged++
	case StatusSkipped:
		s.Skipped++
	default:
		s.Failed++
	}
}

// Total returns the number of processed files.
func (s Stats) Total() int { return s.Created + s.Updated + s.Unchanged + s.Skipped + s.Failed }

// ImportReader imports one FIT file. Failures are reported in the result,
// so a single broken file never aborts a bulk import.
func (im *Importer) ImportReader(ctx context.Context, r io.Reader, origin string) Result {
	res := Result{Origin: origin}
	raw, err := fitfile.ReadAll(r)
	if err != nil {
		return res.fail(err)
	}
	act, err := fitfile.Decode(raw)
	if err != nil {
		return res.fail(err)
	}
	res.Key, res.Sport, res.SubSport = act.Key, act.Sport, act.SubSport
	res.StartTime, res.TZOffsetS, res.DistanceM = act.StartTime, act.TZOffsetS, act.DistanceM

	if err := im.archive(act.SHA256, raw); err != nil {
		return res.fail(fmt.Errorf("archive raw file: %w", err))
	}
	overrides, err := im.Store.Overrides(ctx)
	if err != nil {
		return res.fail(err)
	}
	rec, err := recording(act, origin, overrides)
	if err != nil {
		return res.fail(err)
	}
	res.ActivityID, res.Status, err = im.Store.SaveRecording(ctx, rec)
	if err != nil {
		return res.fail(err)
	}
	im.logger().Debug("imported", "origin", origin, "key", res.Key, "status", res.Status)
	return res
}

// ImportPath imports all FIT files below root (file, directory or ZIP,
// including the Garmin bulk export) and reports each result to fn.
// The returned error is only set for problems with root itself.
func (im *Importer) ImportPath(ctx context.Context, root string, fn func(Result)) (Stats, error) {
	var stats Stats
	err := fitfile.Walk(root, func(src fitfile.Source, r io.Reader) error {
		if err := ctx.Err(); err != nil {
			return err
		}
		origin := src.Path
		if rel, err := filepath.Rel(root, src.Path); err == nil && rel != "." && !filepath.IsAbs(rel) {
			origin = rel
		}
		res := im.ImportReader(ctx, r, origin)
		stats.Add(res)
		if fn != nil {
			fn(res)
		}
		return nil
	})
	return stats, err
}

func (r Result) fail(err error) Result {
	r.Status, r.Error = StatusFailed, err.Error()
	if errors.Is(err, fitfile.ErrNotActivity) {
		r.Status = StatusSkipped
	}
	return r
}

func (im *Importer) logger() *slog.Logger {
	if im.Logger != nil {
		return im.Logger
	}
	return slog.New(slog.DiscardHandler)
}

// archive stores the original file once per content hash. The raw files are
// the source of truth for re-deriving activities after pipeline changes.
func (im *Importer) archive(sha string, raw []byte) error {
	if im.RawDir == "" {
		return nil
	}
	if len(sha) < 2 {
		return errors.New("invalid hash")
	}
	dir := filepath.Join(im.RawDir, sha[:2])
	target := filepath.Join(dir, sha+".fit")
	if _, err := os.Stat(target); err == nil {
		return nil
	}
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, ".import-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(raw); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), target)
}

func recording(act *fitfile.Activity, origin string, overrides []store.Override) (store.Recording, error) {
	stream, err := EncodeStream(&act.Stream)
	if err != nil {
		return store.Recording{}, fmt.Errorf("encode stream: %w", err)
	}
	rec := store.Recording{
		Source: "fit",
		Key:    act.Key,
		SHA256: act.SHA256,
		Origin: origin,
		Activity: store.Activity{
			Sport:              act.Sport,
			SubSport:           act.SubSport,
			StartTime:          act.StartTime,
			TZOffsetS:          act.TZOffsetS,
			DistanceM:          act.DistanceM,
			TimerS:             act.TimerS,
			ElapsedS:           act.ElapsedS,
			AscentM:            act.AscentM,
			DescentM:           act.DescentM,
			AvgSpeed:           act.AvgSpeed,
			MaxSpeed:           act.MaxSpeed,
			AvgHR:              act.AvgHR,
			MaxHR:              act.MaxHR,
			AvgPower:           act.AvgPower,
			MaxPower:           act.MaxPower,
			AvgCadence:         act.AvgCadence,
			DeviceManufacturer: int(act.ManufacturerID),
			DeviceProduct:      int(act.Product),
			DeviceSerial:       int64(act.Serial),
			Training:           store.Training(act.Training),
			AnalysisVersion:    AnalysisVersion,
		},
		Stream: store.Blob{Encoding: StreamEncoding, Data: stream},
	}
	plan := analysis.PlanFor(sport.CategoryOf(act.Sport, act.SubSport).ID)
	if sport.Motorized(act.Sport, act.SubSport) {
		plan = analysis.EffortPlan{SplitM: plan.SplitM}
	}
	rec.Laps = laps(act, plan.SplitM)
	rec.Efforts = efforts(&act.Stream, plan)
	rec.Activity.Thresholds, rec.Activity.Own, rec.Zones = zonesAndLoad(act, overrides)
	if act.BBox != nil {
		b := store.BBox(*act.BBox)
		rec.Activity.BBox = &b
	}
	if ls := geo.Simplify(act.Stream.Lat, act.Stream.Lon); len(ls) >= 2 {
		rec.Track = &store.Track{Points: len(ls), Polyline: geo.EncodePolyline(ls)}
	}
	return rec, nil
}

// EncodeStream serializes a stream in StreamEncoding.
func EncodeStream(s *fitfile.Stream) ([]byte, error) {
	var buf bytes.Buffer
	zw, err := gzip.NewWriterLevel(&buf, gzip.BestCompression)
	if err != nil {
		return nil, err
	}
	if err := json.NewEncoder(zw).Encode(s); err != nil {
		return nil, err
	}
	if err := zw.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// DecodeStream reverses EncodeStream.
func DecodeStream(b store.Blob) (*fitfile.Stream, error) {
	if b.Encoding != StreamEncoding {
		return nil, fmt.Errorf("unsupported stream encoding %q", b.Encoding)
	}
	zr, err := gzip.NewReader(bytes.NewReader(b.Data))
	if err != nil {
		return nil, err
	}
	defer zr.Close()
	var s fitfile.Stream
	if err := json.NewDecoder(zr).Decode(&s); err != nil {
		return nil, err
	}
	return &s, nil
}

// laps returns the device laps, or automatic distance splits when the
// activity was recorded as a single lap.
func laps(act *fitfile.Activity, splitM float64) []store.Lap {
	if len(act.Laps) > 1 {
		out := make([]store.Lap, len(act.Laps))
		for i, l := range act.Laps {
			out[i] = store.Lap{
				StartS: l.StartOffsetS, EndS: l.StartOffsetS + l.ElapsedS, TimerS: l.TimerS, DistanceM: l.DistanceM,
				AscentM: l.AscentM, DescentM: l.DescentM, AvgSpeed: l.AvgSpeed, MaxSpeed: l.MaxSpeed,
				AvgHR: l.AvgHR, MaxHR: l.MaxHR, AvgPower: l.AvgPower, AvgCadence: l.AvgCadence,
			}
		}
		return out
	}
	st := &act.Stream
	if act.DistanceM < 2*splitM {
		return nil
	}
	splits := analysis.Splits(st.T, st.Dist, st.Alt, st.HR, st.Power, splitM)
	out := make([]store.Lap, len(splits))
	for i, sp := range splits {
		elapsed := sp.EndS - sp.StartS
		l := store.Lap{
			Auto: true, StartS: sp.StartS, EndS: sp.EndS, TimerS: elapsed, DistanceM: sp.DistanceM,
			AscentM: int(math.Round(sp.AscentM)), DescentM: int(math.Round(sp.DescentM)),
			AvgHR: int(math.Round(sp.AvgHR)), AvgPower: int(math.Round(sp.AvgPower)),
		}
		if elapsed > 0 {
			l.AvgSpeed = sp.DistanceM / elapsed
		}
		out[i] = l
	}
	return out
}

// efforts computes the best efforts of an activity according to plan.
func efforts(st *fitfile.Stream, plan analysis.EffortPlan) []store.Effort {
	if plan.Group == "" {
		return nil
	}
	var out []store.Effort
	for _, m := range plan.Distances {
		if sec, w, ok := analysis.FastestDistance(st.T, st.Dist, float64(m)); ok {
			out = append(out, store.Effort{Group: plan.Group, Kind: store.EffortDistance, Key: m,
				Value: round1(sec), StartS: round1(w.StartS), EndS: round1(w.EndS)})
		}
	}
	if plan.Power {
		curve := analysis.PowerCurve(st.T, st.Power, analysis.PowerDurations)
		for _, d := range analysis.PowerDurations {
			if p, ok := curve[d]; ok {
				out = append(out, store.Effort{Group: plan.Group, Kind: store.EffortPower, Key: d,
					Value: round1(p.Watts), StartS: p.StartS, EndS: p.EndS})
			}
		}
	}
	if plan.Climb {
		if c, ok := analysis.LargestClimb(st.T, st.Alt, st.Dist); ok {
			out = append(out, store.Effort{Group: plan.Group, Kind: store.EffortClimb,
				Value: round1(c.GainM), StartS: c.StartS, EndS: c.EndS, Extra: round1(c.DistanceM)})
		}
	}
	return out
}

func round1(v float64) float64 { return math.Round(v*10) / 10 }

// Reanalyze re-derives all activities with an older AnalysisVersion from
// their archived raw files and reports each result to fn. Activities whose
// raw file is missing are reported as failed and keep their old data.
func (im *Importer) Reanalyze(ctx context.Context, fn func(Result)) (Stats, error) {
	var stats Stats
	files, err := im.Store.Outdated(ctx, AnalysisVersion)
	if err != nil {
		return stats, err
	}
	for _, f := range files {
		if err := ctx.Err(); err != nil {
			return stats, err
		}
		res := im.reanalyzeOne(ctx, f)
		stats.Add(res)
		if fn != nil {
			fn(res)
		}
	}
	return stats, nil
}

func (im *Importer) reanalyzeOne(ctx context.Context, f store.SourceFile) Result {
	res := Result{Origin: f.Origin, Key: f.Key, ActivityID: f.ActivityID}
	if im.RawDir == "" || len(f.SHA256) < 2 {
		return res.fail(errors.New("raw file unknown"))
	}
	file, err := os.Open(filepath.Join(im.RawDir, f.SHA256[:2], f.SHA256+".fit"))
	if err != nil {
		return res.fail(fmt.Errorf("raw file: %w", err))
	}
	defer file.Close()
	return im.ImportReader(ctx, file, f.Origin)
}

// Outdated reports how many activities Reanalyze would re-derive.
func (im *Importer) Outdated(ctx context.Context) (int, error) {
	files, err := im.Store.Outdated(ctx, AnalysisVersion)
	return len(files), err
}

// zonesAndLoad derives thresholds, time in zones and own load. Garmin's
// time in zones is used as recorded; a manual override valid at the
// activity date (or missing device zones with known thresholds) computes
// the zones from the stream with default zone models instead.
func zonesAndLoad(act *fitfile.Activity, overrides []store.Override) (store.Thresholds, store.OwnLoad, []store.ZoneSeconds) {
	z := act.Zones
	th := store.Thresholds{MaxHR: z.MaxHR, RestHR: z.RestHR, ThresholdHR: z.ThresholdHR, FTP: z.FTP}
	if th.FTP == 0 {
		th.FTP = act.Training.ThresholdPower
	}
	if th != (store.Thresholds{}) {
		th.Source = store.ThresholdsGarmin
	}
	hr, power := fromDevice(store.ZoneHR, z.HR), fromDevice(store.ZonePower, z.Power)
	st := &act.Stream

	local := act.StartTime.Add(time.Duration(act.TZOffsetS) * time.Second)
	day := time.Date(local.Year(), local.Month(), local.Day(), 0, 0, 0, 0, time.UTC)
	if o, ok := store.OverrideAt(overrides, day); ok {
		if o.MaxHR > 0 {
			th.MaxHR, th.Source, hr = o.MaxHR, store.ThresholdsManual, nil
		}
		if o.FTP > 0 {
			th.FTP, th.Source, power = o.FTP, store.ThresholdsManual, nil
		}
	}
	if hr == nil && act.HasHR && th.MaxHR > 0 {
		hr = computed(store.ZoneHR, analysis.HRZoneBounds(th.MaxHR), analysis.TimeInZones(st.T, st.HR, analysis.HRZoneBounds(th.MaxHR)))
	}
	if power == nil && act.HasPower && th.FTP > 0 {
		b := analysis.PowerZoneBounds(th.FTP)
		power = computed(store.ZonePower, b, analysis.TimeInZones(st.T, st.Power, b))
	}

	var own store.OwnLoad
	if act.HasPower {
		np := analysis.NormalizedPower(st.T, st.Power)
		own.NP = int(math.Round(np))
		own.TSS = round1(analysis.TSS(np, th.FTP, act.TimerS))
	}
	if act.HasHR {
		own.TRIMP = round1(analysis.TRIMP(st.T, st.HR, th.RestHR, th.MaxHR, z.Female))
	}
	return th, own, append(hr, power...)
}

func fromDevice(kind string, in []fitfile.ZoneTime) []store.ZoneSeconds {
	out := make([]store.ZoneSeconds, 0, len(in))
	for _, z := range in {
		out = append(out, store.ZoneSeconds{Kind: kind, Zone: z.Zone, Low: z.Low, High: z.High, Seconds: round1(z.Seconds)})
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

func computed(kind string, bounds, seconds []float64) []store.ZoneSeconds {
	if seconds == nil {
		return nil
	}
	out := make([]store.ZoneSeconds, len(bounds))
	for i := range bounds {
		low := 0.0
		if i > 0 {
			low = bounds[i-1]
		}
		out[i] = store.ZoneSeconds{Kind: kind, Zone: i, Low: low, High: bounds[i], Seconds: round1(seconds[i])}
	}
	return out
}

// LatestProfile returns the user profile of the newest activity whose file
// records age and gender, and the start of that activity. Only the newest
// few files are decoded; ok is false if none of them has a profile.
func (im *Importer) LatestProfile(ctx context.Context) (p fitfile.Profile, at time.Time, ok bool, err error) {
	if im.RawDir == "" {
		return p, at, false, nil
	}
	files, err := im.Store.RecentSources(ctx, 10)
	if err != nil {
		return p, at, false, err
	}
	for _, f := range files {
		if len(f.SHA256) < 2 {
			continue
		}
		raw, err := os.ReadFile(filepath.Join(im.RawDir, f.SHA256[:2], f.SHA256+".fit"))
		if err != nil {
			continue
		}
		act, err := fitfile.Decode(raw)
		if err != nil || act.Profile.Age == 0 || act.Profile.Gender == "" {
			continue
		}
		return act.Profile, act.StartTime, true, nil
	}
	return p, at, false, nil
}
